type Config struct {
	// Immediate writes the log line on request instead of response.
	// The request will be logged even if the server crashes, but response
	// data (status code, content length, etc.) cannot be logged.
	Immediate bool

	// Skip determines whether to skip logging for a given request/response pair.
	// Example — only log errors:
	//   Skip: func(r *http.Request, status int) bool { return status < 400 }
	Skip func(r *http.Request, status int) bool

	// Stream is the output writer for log lines. Defaults to os.Stdout.
	Stream io.Writer

	// Buffer enables write buffering. Log lines are flushed to Stream in
	// batches at this interval. Zero disables buffering.
	Buffer time.Duration

	// TrustProxy makes the middleware honour the X-Forwarded-For and
	// X-Forwarded-Proto headers when resolving :remote-addr and :protocol.
	//
	// It is disabled by default and MUST stay disabled unless every request
	// reaching this handler has passed through a reverse proxy you control that
	// overwrites those headers. Any client can set X-Forwarded-For on a direct
	// connection, so trusting it unconditionally lets an attacker forge the
	// address recorded in the access log (and defeat any rate limiting or abuse
	// analysis built on top of it).
	//
	// This mirrors Express, whose "trust proxy" application setting is likewise
	// off by default and which morgan's :remote-addr consults through req.ip.
	TrustProxy bool
}

consts.signature:
const (
	// Combined is the standard Apache combined log format.
	//   :remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"
	Combined Format = `:remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"`

	// Common is the standard Apache common log format.
	//   :remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length]
	Common Format = `:remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length]`

	// Dev is concise output colored by response status, for development use.
	// :status is green for 2xx, cyan for 3xx, yellow for 4xx, red for 5xx, uncolored for 1xx.
	Dev Format = "dev"

	// Short is shorter than default, also including response time.
	//   :remote-addr :remote-user :method :url HTTP/:http-version :status :res[content-length] - :response-time ms
	Short Format = `:remote-addr :remote-user :method :url HTTP/:http-version :status :res[content-length] - :response-time ms`

	// Tiny is the minimal output.
	//   :method :url :status :res[content-length] - :response-time ms
	Tiny Format = `:method :url :status :res[content-length] - :response-time ms`

	// JSON emits each request as a single-line JSON object.
	JSON Format = "json"
)

types.signature:
type Log struct {
	// :date — time the log line is written; use :date[clf], :date[iso], or :date[web].
	DATE time.Time
	// :http-version — HTTP protocol version (e.g. "1.1").
	HTTPVersion string
	// :method — HTTP method of the request.
	METHOD string
	// :pid — process ID of the server process.
	PID int
	// :referrer — Referrer header (falls back to mis-spelled Referer).
	REFERRER string
	// :remote-addr — remote address of the request, parsed as an IP.
	//
	// Deprecated for direct use: an address that is not a bare IP literal (a
	// Unix-socket peer, or a forwarded value carrying a port or a proxy chain)
	// cannot be represented here and leaves the field nil. Read REMOTE_ADDR
	// instead, which always holds the exact textual address the token renders.
	REMOTE_IP IP
	// :remote-addr — the textual remote address, exactly as rendered by the
	// token. Populated by FromRequest; when empty the token falls back to
	// REMOTE_IP so that Log values built by hand keep working.
	REMOTE_ADDR string
	// :protocol — "http" or "https" as observed for this request.
	PROTOCOL string
	// :remote-user — user authenticated via Basic auth.
	REMOTE_USER string
	// :req[header] — a specific request header; read live from *http.Request via the token.
	REQUEST_HEADER string
	// :res[header] — response headers captured after the handler runs.
	RESPONSE_HEADERS http.Header
	// RESPONSE_SIZE is the number of body bytes the handler wrote, or -1 when
	// the size is unknown (for example under Config.Immediate, or after the
	// connection was hijacked). It backs the :res[content-length] fallback
	// described on that token: Go's net/http computes Content-Length inside the
	// server rather than storing it in the header map, so without this counter
	// the token would render "-" for responses where Node morgan prints a size.
	RESPONSE_SIZE int64
	// RESPONSE_STREAMED reports whether the handler flushed the response before
	// returning. A streamed (chunked) response has no Content-Length in Node
	// either, so :res[content-length] does not fall back to RESPONSE_SIZE when
	// this is true.
	RESPONSE_STREAMED bool
	// :response-time[digits] — time from request arrival to response headers written, in ms.
	RESPONSE_TIME time.Duration
	// :status — HTTP status code; "-" if the cycle completed before a response was sent.
	STATUS int
	// :total-time[digits] — time from request arrival to response fully written, in ms.
	TOTAL_TIME time.Duration
	// :url — request URL path (with query string if present).
	URL string
	// :user-agent — User-Agent header.
	USER_AGENT string
	// :incoming — size of the incoming request body in bytes (-1 if unknown).
	INCOMING int64
}

funcs.doc:
Token registers (or overwrites) a named token available as :name or :name[arg]
in format strings.

Example:

	morgan.Token("type", func(r *http.Request, log morgan.Log, args ...string) string {
	    return r.Header.Get("Content-Type")
	})

