package main

import (
	"fmt"
	"time"

	"github.com/malcolmston/morgan"
)

func main() {
	t := time.Date(2024, time.November, 27, 6, 21, 42, 0, time.UTC)
	fmt.Println(morgan.Clfdate(t))
	fmt.Println(morgan.FormatDuration(1500*time.Microsecond, 3))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

func main() {
	var buf strings.Builder

	app := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "ok")
	})

	logged := morgan.New(app, morgan.Tiny, morgan.Config{Stream: &buf})

	req := httptest.NewRequest(http.MethodGet, "/hi", nil)
	rec := httptest.NewRecorder()
	logged.ServeHTTP(rec, req)

	fmt.Println(strings.Contains(buf.String(), "GET /hi 200"))
}

