// okHandler writes a fixed 11-byte body, so :res[content-length] is predictable.
var okHandler = http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
	fmt.Fprint(w, "hello world")
})

func main() {
	morgan.RegisterFormat("audit", ":method :url :status :req[x-request-id]")

	var buf strings.Builder
	logged := morgan.New(okHandler, "audit", morgan.Config{Stream: &buf})

	req := httptest.NewRequest(http.MethodGet, "/things", nil)
	req.Header.Set("X-Request-ID", "abc-123")
	logged.ServeHTTP(httptest.NewRecorder(), req)

	fmt.Print(buf.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

// serve drives one request through a middleware and returns the trimmed log
// output, keeping the examples below focused on the option being shown.
func serve(h http.Handler, buf *strings.Builder, method, target string) string {
	h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(method, target, nil))
	return strings.TrimRight(buf.String(), "\n")
}

func main() {
	morgan.RegisterFormatFunc("logfmt", func(_ *http.Request, log morgan.Log) string {
		return fmt.Sprintf("method=%s url=%s status=%d class=%s",
			log.METHOD, log.URL, log.STATUS, morgan.StatusCategory(log.STATUS))
	})

	var buf strings.Builder
	app := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "gone", http.StatusGone)
	})
	logged := morgan.New(app, "logfmt", morgan.Config{Stream: &buf})

	fmt.Println(serve(logged, &buf, http.MethodGet, "/old"))
}

