package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

// okHandler writes a fixed 11-byte body, so :res[content-length] is predictable.
var okHandler = http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
	fmt.Fprint(w, "hello world")
})

func main() {
	morgan.Token("cookie", func(r *http.Request, _ morgan.Log, args ...string) string {
		if r == nil || len(args) == 0 {
			return ""
		}
		c, err := r.Cookie(args[0])
		if err != nil {
			return ""
		}
		return c.Value
	})

	var buf strings.Builder
	logged := morgan.New(okHandler, ":method :url :cookie[session]", morgan.Config{Stream: &buf})

	req := httptest.NewRequest(http.MethodGet, "/dash", nil)
	req.AddCookie(&http.Cookie{Name: "session", Value: "s-42"})
	logged.ServeHTTP(httptest.NewRecorder(), req)

	fmt.Print(buf.String())
}

