import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"time"

	"github.com/malcolmston/morgan"
)

// lockedBuffer is a trivially synchronised sink, used by the buffered-output
// example where a timer goroutine performs the write.
type lockedBuffer struct {
	mu sync.Mutex
	b  strings.Builder
}

func (l *lockedBuffer) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}

func (l *lockedBuffer) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.String()
}

// okHandler writes a fixed 11-byte body, so :res[content-length] is predictable.
var okHandler = http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
	fmt.Fprint(w, "hello world")
})

func main() {
	// The flush happens on a timer goroutine, so the example reads the sink
	// under a lock. A real destination (an *os.File, a network writer) needs no
	// such care.
	buf := &lockedBuffer{}
	logged := morgan.New(okHandler, ":method :url :status",
		morgan.Config{Stream: buf, Buffer: 20 * time.Millisecond})

	logged.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/a", nil))
	logged.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/b", nil))
	fmt.Println("written before the interval elapses:", buf.String() != "")

	time.Sleep(200 * time.Millisecond)
	fmt.Print(buf.String())
}

