package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

func main() {
	var buf strings.Builder

	app := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/missing" {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
		fmt.Fprint(w, "ok")
	})

	cfg := morgan.Config{
		Stream: &buf,
		Skip: func(_ *http.Request, status int) bool {
			return status < 400
		},
	}
	logged := morgan.New(app, morgan.Tiny, cfg)

	okReq := httptest.NewRequest(http.MethodGet, "/ok", nil)
	logged.ServeHTTP(httptest.NewRecorder(), okReq)
	fmt.Println("logged after success:", buf.Len() > 0)

	missReq := httptest.NewRequest(http.MethodGet, "/missing", nil)
	logged.ServeHTTP(httptest.NewRecorder(), missReq)
	fmt.Println("has 404 line:", strings.Contains(buf.String(), "GET /missing 404"))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

// okHandler writes a fixed 11-byte body, so :res[content-length] is predictable.
var okHandler = http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
	fmt.Fprint(w, "hello world")
})

func main() {
	request := func() *http.Request {
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		r.RemoteAddr = "198.51.100.4:44321"
		r.Header.Set("X-Forwarded-For", "203.0.113.9")
		return r
	}

	var def strings.Builder
	morgan.New(okHandler, ":remote-addr", morgan.Config{Stream: &def}).
		ServeHTTP(httptest.NewRecorder(), request())
	fmt.Print("default:     ", def.String())

	var trusted strings.Builder
	morgan.New(okHandler, ":remote-addr", morgan.Config{Stream: &trusted, TrustProxy: true}).
		ServeHTTP(httptest.NewRecorder(), request())
	fmt.Print("trustproxy:  ", trusted.String())
}

package main

import (
	"fmt"
	"net/http"
	"time"

	"github.com/malcolmston/morgan"
)

func main() {
	log := morgan.Log{
		DATE:             time.Date(2024, time.November, 27, 6, 21, 42, 0, time.UTC),
		HTTPVersion:      "1.1",
		METHOD:           "GET",
		URL:              "/index.html",
		REMOTE_ADDR:      "203.0.113.7",
		REMOTE_USER:      "tj",
		REFERRER:         "http://example.com/",
		USER_AGENT:       "curl/8.7.1",
		STATUS:           200,
		RESPONSE_TIME:    1500 * time.Microsecond,
		RESPONSE_HEADERS: http.Header{"Content-Length": []string{"1024"}},
	}

	for _, f := range []morgan.Format{morgan.Combined, morgan.Common, morgan.Short, morgan.Tiny} {
		fmt.Println(morgan.Compile(string(f))(nil, log))
	}
}

package main

import (
	"fmt"

	"github.com/malcolmston/morgan"
)

func main() {
	line := morgan.Compile(":method :url :status")

	log := morgan.Log{METHOD: "POST", URL: "/orders", STATUS: 201}
	fmt.Println(line(nil, log))

	// Unknown tokens and empty values both render as a dash, exactly as in the
	// Node library.
	dashes := morgan.Compile(":method :nope :status")
	fmt.Println(dashes(nil, morgan.Log{METHOD: "GET"}))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/malcolmston/morgan"
)

func main() {
	var buf strings.Builder
	app := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/boom" {
			http.Error(w, "boom", http.StatusInternalServerError)
			return
		}
		fmt.Fprint(w, "ok")
	})

	logged := morgan.New(app, ":method :url :status", morgan.Config{
		Stream: &buf,
		Skip: morgan.CombineSkips(
			morgan.SkipPaths("/healthz", "/metrics"),
			morgan.SkipUserAgents("kube-probe"),
			morgan.SkipStatusBelow(400),
		),
	})

	for _, target := range []string{"/healthz", "/metrics", "/ok", "/boom"} {
		logged.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, target, nil))
	}
	fmt.Print(buf.String())
}
